#include <stdlib.h>

int *make_value(void) {
    int *p = malloc(sizeof *p);
    if (p != NULL) *p = 42;
    return p;
}

int main(void) {
    int *value = make_value();
    if (value == NULL) return 1;
    int result = *value;
    free(value);
    value = NULL;
    return result == 42 ? 0 : 1;
}

#include <stdio.h>

void use_value(const int *value) {
    if (value != NULL) printf("%d\n", *value);
}

int main(void) {
    int local = 25;
    use_value(&local);
    return 0;
}
